import { http as unauthedHttp } from '@hubspot/local-dev-lib/http/unauthed';
const USAGE_PATH = 'local/dev/tools/proxy/v1/usage';
export async function sendUsageEvent(request) {
    try {
        await unauthedHttp.post({
            url: USAGE_PATH,
            data: request,
        });
    }
    catch (_e) { }
}
